const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const AI_MODEL = norm($env.AI_MODEL) || 'llama-3.3-70b-versatile';
const aiRequest = (system, user, temperature) => ({
  model: AI_MODEL, temperature: temperature === undefined ? 0.7 : temperature, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
});
const parseAi = (resp) => {
  const raw = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
  if (!raw) throw new Error('AI provider returned no content');
  let s = String(raw).trim();
  const m = s.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (m) s = m[1].trim();
  try { return JSON.parse(s); } catch (e) { throw new Error('AI provider returned invalid JSON: ' + e.message); }
};
// Pick today's calendar row from LAUNCH_DATE. Skip outside the 30-day window or if a draft already exists.
const launch = norm($env.LAUNCH_DATE);
if (!/^\d{4}-\d{2}-\d{2}$/.test(launch)) throw new Error('LAUNCH_DATE env var must be set to YYYY-MM-DD');
const dayNumber = Math.floor((Date.now() - Date.parse(launch + 'T00:00:00Z')) / 86400000) + 1;
if (dayNumber < 1 || dayNumber > 30) return [];
const cal = $('Read Content Calendar').all().map((i) => i.json);
const row = cal.find((r) => parseInt(r.day_number, 10) === dayNumber);
if (!row) throw new Error('No Content Calendar row for day_number ' + dayNumber);
const drafts = $input.all().map((i) => i.json);
if (drafts.some((d) => parseInt(d.day_number, 10) === dayNumber)) return [];
const system = 'You are a professional social media content creator and copywriter for Eki, a digital marketplace connecting African foodstuff vendors with global buyers.\n\nGenerate structured content outputs based on the topics provided. Return output strictly in JSON format matching this structure:\n{\n  "hook": "One scroll-stopping sentence",\n  "caption": "Engagement caption (50-150 words) with emojis",\n  "hashtags": "#Hashtags #RelatedToTopic #EkiMarket",\n  "video_script": "Short-form 30-sec script with visual cues in brackets, e.g. [Visual: Exporter sealing bag] followed by audio text."\n}\nDo not invent statistics, testimonials, prices, or guarantees.';
const user = 'Today\'s Content Plan:\nPlatform: ' + norm(row.suggested_platform) + '\nPillar: ' + norm(row.pillar) + '\nTopic: ' + norm(row.topic_brief) + '\nSuggested Hook: ' + norm(row.suggested_hook) + '\nCTA: ' + norm(row.cta) + '\nTarget Audience: ' + norm(row.target_audience);
return [{ json: { day_number: dayNumber, platform: norm(row.suggested_platform).split(',')[0].trim() || 'Instagram', ai_request: aiRequest(system, user, 0.8) } }];

