const ai = parseAi($input.first().json);
const src = $('Select Today Row').first().json;
for (const f of ['hook', 'caption', 'hashtags', 'video_script']) { if (typeof ai[f] !== 'string' || !ai[f].trim()) throw new Error('AI output missing field: ' + f); }
const today = new Date().toISOString().slice(0, 10);
const draft = {
  draft_id: 'D-' + String(src.day_number).padStart(3, '0') + '-' + today.replace(/-/g, ''),
  day_number: String(src.day_number), platform: src.platform, hook: ai.hook.trim(), caption: ai.caption.trim(),
  hashtags: ai.hashtags.trim(), video_script: ai.video_script.trim(), status: 'Draft',
  approval_date: '', published_date: '', publish_time: '', row_number: '', published: 'FALSE', created_date: today,
};
const text = 'New Eki content draft ready for approval\n\nDay: ' + draft.day_number + '\nPlatform: ' + draft.platform + '\n\nHook: ' + draft.hook + '\n\nCaption:\n' + draft.caption + '\n\nHashtags: ' + draft.hashtags + '\n\nVideo script:\n' + draft.video_script + '\n\nReply with:\n/approve ' + draft.day_number + '\n/reject ' + draft.day_number + '\n/edit ' + draft.day_number + ' [your edits]';
return [{ json: { draft, text } }];
